  await ui.setToday(pg_uma, "2026-03-25");
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "1.00"}));
  expect(await ui.editPerson(pg_uma, p_ben, {"grade": "B"})).toBe(true);
  expect(await ui.pasteClaims(pg_uma, "Ben,20.00,2026-04-02,paste\nAda,0.40,,a, b")).toBe(2);
  const c_ben_1 = await ui.claimAt(pg_uma, p_ben, 1);
  const c_ada_0 = await ui.claimAt(pg_uma, p_ada, 0);
  await ui.refresh(pg_uma);
  const c_ben_2 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "99.95", "date": "2026-03-28"}));
  expect(await ui.statementAsOf(pg_uma, p_ada, "2026-02-10")).toBe(false);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.delegate(pg_vic, {"user": "uma", "from": "2026-02-25", "to": "2026-03-05"})).toBe(true);
  await ui.refresh(pg_uma);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
  expect(await ui.claimAction(pg_uma, c_ben_0, "open")).toBe(true);
  await ui.refresh(pg_uma);
  expect(await ui.addClaim(pg_uma, p_cam, {"amount": "12.50", "date": "2026-02-25"})).toBeNull();
  expect(await ui.claimAction(pg_uma, c_ben_1, "void")).toBe(false);
  await ui.setToday(pg_uma, "2026-04-06");
  const c_ben_3 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "10.25", "date": "2026-03-20"}));
  await ui.refresh(pg_uma);
