  expect(await ui.redate(pg_wes, c_ben_0, "2026-03-28")).toBe(false);
  await ui.refresh(pg_wes);
  expect(await ui.redate(pg_wes, c_ben_0, "2026-04-02")).toBe(false);
  await ui.setAsOf(pg_wes, "2026-03-05");
  await ui.refresh(pg_wes);

